SELECT * FROM (SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'EX:' || result_id event_id, student_id case_id, 'Degree Examination Taken' activity, examination_date timestamp FROM degree_examination_result UNION ALL SELECT 'REG:' || student_id || ':' || course_id event_id, student_id case_id, 'Course Registered' activity, registration_time timestamp FROM registration UNION ALL SELECT 'GRADE:' || g.assignment_id || ':' || g.instructor_id || ':' || g.grading_time event_id, a.student_id case_id, 'Assignment Graded' activity, g.grading_time timestamp FROM assignment_grading g JOIN assignment a ON a.assignment_id=g.assignment_id UNION ALL SELECT 'SIM:' || student_id || ':' || module_id || ':' || simulation_date event_id, student_id case_id, 'Simulation Experiment Completed' activity, simulation_date timestamp FROM student_simulation_experiment_result UNION ALL SELECT 'THESIS:' || thesis_id event_id, student_id case_id, 'Thesis Submitted' activity, submission_date timestamp FROM thesis) UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM registration_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM degree_examination_result_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM assignment_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM simulation_module_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM student_simulation_experiment_result_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM thesis_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM course_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM task_activity) e JOIN (SELECT event_id, case_id FROM (SELECT * FROM (SELECT 'EX:' || result_id event_id, student_id case_id, 'Degree Examination Taken' activity, examination_date timestamp FROM degree_examination_result UNION ALL SELECT 'REG:' || student_id || ':' || course_id event_id, student_id case_id, 'Course Registered' activity, registration_time timestamp FROM registration UNION ALL SELECT 'GRADE:' || g.assignment_id || ':' || g.instructor_id || ':' || g.grading_time event_id, a.student_id case_id, 'Assignment Graded' activity, g.grading_time timestamp FROM assignment_grading g JOIN assignment a ON a.assignment_id=g.assignment_id UNION ALL SELECT 'SIM:' || student_id || ':' || module_id || ':' || simulation_date event_id, student_id case_id, 'Simulation Experiment Completed' activity, simulation_date timestamp FROM student_simulation_experiment_result UNION ALL SELECT 'THESIS:' || thesis_id event_id, student_id case_id, 'Thesis Submitted' activity, submission_date timestamp FROM thesis)) UNION ALL SELECT event_id,case_id FROM lifecycle_case_link WHERE case_table='student') m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id) WHERE activity IN ('Assignment Assigned','Assignment Submitted','Assignment Graded') ORDER BY case_id,timestamp,event_id;
